// MT2009_PLUS_EARLY_PACKET_V1 (skip) (server-patches/enginefixes): a chat
// command or a whisper that reaches a connection before it is in the game -
// still saying hello (handshake) or loading (login phase) - is passed over
// whole. Both phases used to read only its fixed head and took the text after
// it for the next packets: an unknown header, and the connection was closed.
// The Companion's window (P) polls the server with "/towarzysz" and its poll
// could leave right after a channel change or a teleport had opened the new
// connection, so every such change ended on the login screen.
int Mt2009PlusSkipEarlyPacket(LPDESC d, BYTE bHeader, const char * c_pData, int iBufferLeft)
{
	const int iHead = bHeader == HEADER_CG_WHISPER ? (int) sizeof(TPacketCGWhisper) : (int) sizeof(TPacketCGChat);
	if (iBufferLeft < iHead)
		return -1;
	const WORD wSize = *reinterpret_cast<const WORD *>(c_pData + sizeof(BYTE));
	if ((int) wSize < iHead)
	{
		sys_err("early packet %u with a bad size %u (fd %d)", bHeader, wSize, d->GetSocket());
		d->SetPhase(PHASE_CLOSE);
		return -1;
	}
	if (iBufferLeft < (int) wSize)
		return -1;
	sys_log(0, "early packet %u (%u bytes) passed over before the game phase (fd %d)", bHeader, wSize, d->GetSocket());
	return (int) wSize - iHead;
}

